    public String connectToURL(String url, String params) {
        String httpResponse = null;
        if (!isCmwap()) {
            try {
                String requestURL = (url + params).replaceAll(" ", "%20");
                AppLog.i(URL_CONNECTION, "baseURL: " + url);
                AppLog.i(URL_CONNECTION, "requestURL: " + requestURL);
                HttpUriRequest http = new HttpGet(requestURL);
                HttpParams httpParameters = new BasicHttpParams();
                HttpConnectionParams.setConnectionTimeout(httpParameters, 15000);
                HttpConnectionParams.setSoTimeout(httpParameters, 30000);
                HttpResponse response = new DefaultHttpClient(httpParameters).execute(http);
                HttpEntity entity = response.getEntity();
                httpResponse = EntityUtils.toString(entity);
                AppLog.i(URL_CONNECTION, "--------------------");
                AppLog.i(URL_CONNECTION, "response status: " + response.getStatusLine().getStatusCode());
                AppLog.i(URL_CONNECTION, "response size: " + httpResponse.length());
                AppLog.i(URL_CONNECTION, "response: ");
                AppLog.i(URL_CONNECTION, "" + httpResponse);
                AppLog.i(URL_CONNECTION, "--------------------");
                return httpResponse;
            } catch (Exception e) {
                AppLog.e(URL_CONNECTION, "Exception: " + e.toString());
                return httpResponse;
            }
        }
        try {
            HttpHost proxy = new HttpHost("10.0.0.172", 80, "http");
            HttpHost target = new HttpHost("app.dwap.com", 8000, "http");
            String requestURL2 = (url + params).replaceAll(" ", "%20").replaceFirst("http://app.dwap.com:8000", "");
            AppLog.i(URL_CONNECTION, "baseURL: " + url);
            AppLog.i(URL_CONNECTION, "requestURL: " + requestURL2);
            HttpRequest http2 = new HttpGet(requestURL2);
            HttpParams httpParameters2 = new BasicHttpParams();
            HttpConnectionParams.setConnectionTimeout(httpParameters2, 15000);
            HttpConnectionParams.setSoTimeout(httpParameters2, 30000);
            HttpClient client = new DefaultHttpClient(httpParameters2);
            client.getParams().setParameter("http.route.default-proxy", proxy);
            HttpResponse response2 = client.execute(target, http2);
            HttpEntity entity2 = response2.getEntity();
