                    newpath = url.substring(url.indexOf(";") + 1);
                } else {
                    package_str = url.substring("load://".length());
                }
                Log.i("pathpathpaht", newpath);
                if (package_str != "") {
                    String open_package = package_str;
                    PackageManager localPackageManager = OffersWebView.this.getPackageManager();
                    Intent tmpIntent = null;
                    try {
                        tmpIntent = localPackageManager.getLaunchIntentForPackage(open_package);
                    } catch (Exception e1) {
                        e1.printStackTrace();
                    }
                    if (tmpIntent != null) {
                        OffersWebView.this.startActivity(tmpIntent);
                    } else {
                        if (url.indexOf("market") > -1) {
                            try {
                                String[] str = newpath.split("id=");
                                String composeedURL = "market://details?id=" + str[1];
                                Intent intent = new Intent("android.intent.action.VIEW", Uri.parse(composeedURL));
                                OffersWebView.this.startActivity(intent);
                            } catch (Exception e) {
                                OffersWebView.this.dialog = new AlertDialog.Builder(OffersWebView.this).setTitle("").setMessage("Android market is unavailable at this device. To view this link install market.").setPositiveButton("确定", new DialogInterface.OnClickListener() { // from class: com.waps.OffersWebView.AppWebViewClient.1
                                    @Override // android.content.DialogInterface.OnClickListener
                                    public void onClick(DialogInterface dialog, int whichButton) {
