                                    }
                                }).create();
                                try {
                                    OffersWebView.this.dialog.show();
                                } catch (Exception exp) {
                                    exp.printStackTrace();
                                }
                            }
                        } else {
                            view.loadUrl(newpath);
                        }
                        return true;
                    }
                }
            }
            return false;
        }
    }

