        System.out.println("gameView.isWin = " + this.gameView.isWin);
        if (gameAction == GameView.NEWGAME) {
            if (this.gameView.isWin) {
                System.out.println(this.PointTotal);
                if (this.PointTotal > 1) {
                    wapsSpendPoint(1);
                    this.gameView.gameAction(GameView.NEWGAME, this.isLimited);
                    return;
                } else {
