    protected void cardDoubleTap() {
        this.mIndexFrom = this.mIndex;
        boolean result = false;
        if (this.mCardsStacks[this.mIndexFrom].isEmpty()) {
            this.mIndexFrom = -1;
            this.mIndexTo = -1;
            this.mIndex = -1;
            return;
        }
        if (this.mIndexFrom < 8) {
            int i = 8;
            while (true) {
                if (i >= 12) {
                    break;
                }
                this.mIndexTo = i;
                if (!moveCards()) {
                    i++;
                } else {
                    result = true;
                    break;
                }
            }
        } else if (this.mIndexFrom < 12) {
            int i2 = 12;
            while (true) {
                if (i2 >= 16) {
                    break;
                }
                if (!moveCards()) {
                    i2++;
                } else {
                    result = true;
                    break;
                }
            }
        }
        if (result) {
            extraMove();
            this.mIndexFrom = -1;
            this.mIndexTo = -1;
            this.mIndex = -1;
            winCheck();
            drawAll();
        }
    }

