    private boolean extraCheck(int temp) {
        int t = 0;
        int u = temp / 13;
        int v = temp % 13;
        switch (u) {
            case 0:
                u = (v + 13) - 1;
                v = (v + 26) - 1;
                break;
            case 1:
                u = v - 1;
                v = (v + 39) - 1;
                break;
            case 2:
                u = v - 1;
                v = (v + 39) - 1;
                break;
            case 3:
                u = (v + 13) - 1;
                v = (v + 26) - 1;
                break;
        }
        for (int k = 12; k < 16; k++) {
            if (!this.mCardsStacks[k].isEmpty() && this.mCardsStacks[k].contains(Integer.valueOf(u))) {
                t++;
            }
            if (!this.mCardsStacks[k].isEmpty() && this.mCardsStacks[k].contains(Integer.valueOf(v))) {
                t++;
            }
        }
        return t == 2;
    }

