    public void extraMove() {
        int i = 0;
        while (i < 12) {
            if (!this.mCardsStacks[i].isEmpty()) {
                int temp = this.mCardsStacks[i].peek().intValue();
                if (temp % 13 < 2) {
                    int j = 12;
                    while (true) {
                        if (j < 16) {
                            this.mIndexFrom = i;
                            this.mIndexTo = j;
                            if (!moveCards()) {
                                j++;
                            } else {
                                i = -1;
                                break;
                            }
                        }
                    }
                } else {
                    int j2 = 12;
                    while (true) {
                        if (j2 < 16) {
                            if (this.mCardsStacks[j2].isEmpty() || temp - this.mCardsStacks[j2].peek().intValue() != 1 || !extraCheck(temp)) {
                                j2++;
                            } else {
                                this.mCardsStacks[j2].push(this.mCardsStacks[i].pop());
                                i = -1;
                                break;
                            }
                        } else {
                            break;
                        }
                    }
                }
            }
            i++;
        }
    }

