    private void setGameNumber(boolean isLimited) {
        if (isLimited) {
            Date date = new Date();
            int seed = ((date.getYear() + 1900) * 1000000) + ((date.getMonth() + 1) * 10000) + (date.getDate() * 100);
            Random random = new Random();
            random.setSeed(seed + random.nextInt(10));
            this.mGameNumber = random.nextInt(1000001);
            return;
        }
        this.mGameNumber = (int) Math.ceil(Math.random() * 1000000.0d);
    }

