    public void winCheck() {
        for (int i = 0; i < 8; i++) {
            if (!this.mCardsStacks[i].isEmpty()) {
                for (int j = 1; j < this.mCardsStacks[i].size(); j++) {
                    if (!rbCheck(this.mCardsStacks[i].get(j - 1).intValue(), this.mCardsStacks[i].get(j).intValue())) {
                        return;
                    }
                }
            }
        }
        new AlertDialog.Builder(this.mGameControl).setMessage(R.string.message_win).setPositiveButton(R.string.button_yes, new DialogInterface.OnClickListener() { // from class: org.pcmac.freecell.GameView.3
